import React from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import NavBar from './NavBar';

const styles = `
.profesor-page-container {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 90%;
  max-width: 900px;
  margin: 32px auto 0 auto;
  min-height: 60%;
  font-family: 'Segoe UI', Arial, sans-serif;
}
.profesor-image {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  object-fit: cover;
  background: #eee;
  margin-right: 40px;
  box-shadow: 0 2px 12px rgba(25, 118, 210, 0.10);
}
.profesor-info {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}
.profesor-name {
  font-size: 1.5rem;
  font-weight: 700;
  color: #222;
  margin-bottom: 10px;
}
.profesor-title {
  font-size: 1.1rem;
  color: #1976d2;
  font-weight: 500;
}
`;

const ProfesorPage = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const profesor = location.state?.profesor;

  React.useEffect(() => {
    if (!document.getElementById('profesor-page-styles')) {
      const style = document.createElement('style');
      style.id = 'profesor-page-styles';
      style.innerHTML = styles;
      document.head.appendChild(style);
    }
  }, []);

  if (!profesor) {
    // Ako nema podataka, vrati korisnika na početnu
    navigate('/');
    return null;
  }
return (
  <>
    <NavBar />
    <div className="profesor-page-container">
      <div style={{ display: 'flex', alignItems: 'center', marginBottom: 0, justifyContent: 'flex-start', width: '100%', maxWidth: 900 }}>
        <div
          className="profesor-image"
          style={{
            width: 200,
            height: 200,
            marginTop: '17%',
            borderRadius: '50%',
            background: '#eee',
            marginRight: 40,
            boxShadow: '0 2px 12px rgba(25, 118, 210, 0.10)',
            display: 'flex',
            alignItems: 'left',
            justifyContent: 'left',
            fontSize: '2.5rem',
            fontWeight: 700,
            color: '#1976d2',
            textTransform: 'uppercase',
            userSelect: 'none',
          }}
        >
          {profesor.name.trim().split(/\s+/).map(word => word[0]).join('')}
        </div>
        <div className="profesor-info">
          <div className="profesor-name">{profesor.name}</div>
          <div className="profesor-title">{profesor.title}</div>
        </div>
      </div>
    </div>
    {/* Modalni prozor za teme ispod cijelog kontejnera */}
    {profesor.topics && profesor.topics.length > 0 && (
      <div
        style={{
          position: 'relative',
          width: '90%',
         margin: '0 auto',
          background: '#fff',
          borderRadius: 18,
          boxShadow: '0 4px 24px rgba(25,118,210,0.10)',
          padding: '20px',
          textAlign: 'left',
          
        }}
      >
        <div
          style={{
            color: '#1976d2',
            fontWeight: 600,
            marginBottom: 12,
            textTransform: 'uppercase',
            fontSize: '1.1rem',
            letterSpacing: '0.04em',
          }}
        >
          Teme:
        </div>
        <ul style={{ margin: 0, paddingLeft: 32 }}>
          {profesor.topics.map((topic, idx) => (
            <li key={idx} style={{ fontSize: '1.08rem', color: '#333', marginBottom: 4 }}>
              {topic}
            </li>
          ))}
        </ul>
      </div>
    )}
  </>
);
};

export default ProfesorPage;
